CodeInjections.CodeInjection:
float3 position = In.position.xyz * object.cargoScale;
#if defined(SKINNING)
    return skinPoint(position, In, instance, object);
#else
    return position;
#endif

float3 position = In.position.xyz * object.cargoScale;
#if defined(SKINNING)
    return skinPrevPoint(position, In, instance, object);
#else
    return position;
#endif

float3 normal = normalize(In.normal.xyz / object.cargoScale);
#if defined(SKINNING)
    return skinVector(normal, In, instance, object);
#else
    return normal;
#endif

float3 tangent = normalize(In.tangent.xyz * object.cargoScale);
#if defined(SKINNING)
    return skinVector(tangent, In, instance, object);
#else
    return tangent;
#endif
